create extension if not exists pgcrypto;
create table if not exists integration_connections(id uuid primary key default gen_random_uuid(),provider text not null,external_user_id text,status text not null default 'pending',scopes text[] not null default '{}',access_token_encrypted text,refresh_token_encrypted text,token_expires_at timestamptz,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,external_user_id));
create table if not exists raw_events(id uuid primary key default gen_random_uuid(),provider text not null,external_id text not null,event_type text not null,payload jsonb not null,received_at timestamptz not null default now(),processed_at timestamptz,unique(provider,external_id,event_type));
create table if not exists metrics(id uuid primary key default gen_random_uuid(),provider text not null,external_id text not null,type text not null,recorded_at timestamptz not null,ended_at timestamptz,value double precision,unit text,data jsonb not null default '{}',raw_event_id uuid references raw_events(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,external_id,type));
create index if not exists metrics_type_recorded_at_idx on metrics(type,recorded_at desc);
create table if not exists sync_runs(id uuid primary key default gen_random_uuid(),provider text not null,status text not null,started_at timestamptz,finished_at timestamptz,error text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
alter table integration_connections enable row level security;alter table raw_events enable row level security;alter table metrics enable row level security;alter table sync_runs enable row level security;
